_NAME], [t0].[REMARK] AS [REMARK], [t0].[EFNETStatus] AS [EFNETStatus2], [t16].[SequenceNumber] AS [MO_DEMAND_SequenceNumber], CASE [t16].[DEMAND_DOC_RTK] WHEN N'SALES_ORDER_DOC.SALES_ORDER_DOC_D.SALES_ORDER_DOC_SD' THEN '销售订单' WHEN N'MO' THEN '工单' END AS [MO_DEMAND_DEMAND_DOC_RTK], CASE [t16].[DEMAND_DOC_RTK] WHEN N'SALES_ORDER_DOC.SALES_ORDER_DOC_D.SALES_ORDER_DOC_SD' THEN ( [t19].[DOC_NO] + ( N'-' + ( CAST ( [t21].[SequenceNumber] AS NVarChar ) + ( N'-' + CAST ( [t22].[SequenceNumber] AS NVarChar ) ) ) ) ) WHEN N'TRANSFER_REQUISITION.TRANSFER_REQUISITION_D' THEN ( [t24].[DOC_NO] + ( N'-' + CAST ( [t25].[SequenceNumber] AS NVarChar ) ) ) WHEN N'INNER_ORDER_DOC.INNER_ORDER_DOC_D.INNER_ORDER_DOC_SD' THEN ( [t28].[DOC_NO] + ( N'-' + ( CAST ( [t30].[SequenceNumber] AS NVarChar ) + ( N'-' + CAST ( [t31].[SequenceNumber] AS NVarChar ) ) ) ) ) WHEN N'STOCKING_PLAN.STOCKING_PLAN_D' THEN ( [t33].[STOCKING_PLAN_NO] + ( N'-' + CAST ( [t34].[SequenceNumber] AS NVarChar ) ) ) END AS [DEMAND_DOC_ROID], [t0].[DEMAND_NO] AS [DEMAND_NO], CASE [t16].[DEMAND_DOC_RTK] WHEN N'MO' THEN [t36].[ITEM_CODE] WHEN N'DISTRIBUTION_LIST' THEN [t38].[ITEM_CODE] WHEN N'SALES_ORDER_DOC.SALES_ORDER_DOC_D.SALES_ORDER_DOC_SD' THEN [t39].[ITEM_CODE] WHEN N'STOCKING_PLAN.STOCKING_PLAN_D' THEN [t32].[ITEM_CODE] WHEN N'INNER_ORDER_DOC.INNER_ORDER_DOC_D.INNER_ORDER_DOC_SD' THEN [t40].[ITEM_CODE] WHEN N'FORECAST.FORECAST_D' THEN [t42].[ITEM_CODE] END AS [REFERENCE_SOURCE_ID_ITEM_ID_CODE], CASE [t16].[DEMAND_DOC_RTK] WHEN N'MO' THEN [t36].[ITEM_NAME] WHEN N'DISTRIBUTION_LIST' THEN [t38].[ITEM_NAME] WHEN N'SALES_ORDER_DOC.SALES_ORDER_DOC_D.SALES_ORDER_DOC_SD' THEN [t39].[ITEM_NAME] WHEN N'STOCKING_PLAN.STOCKING_PLAN_D' THEN [t32].[ITEM_NAME] WHEN N'INNER_ORDER_DOC.INNER_ORDER_DOC_D.INNER_ORDER_DOC_SD' THEN [t40].[ITEM_NAME] WHEN N'FORECAST.FORECAST_D' THEN [t42].[ITEM_NAME] END AS [REFERENCE_SOURCE_ID_ITEM_ID_NAME], CASE [t16].[DEMAND_DOC_RTK] WHEN N'MO' THEN [t36].[ITEM_SPECIFICATION] WHEN N'DISTRIBUTION_LIST' THEN [t38].[ITEM_SPECIFICATION] WHEN N'SALES_ORDER_DOC.SALES_ORDER_DOC_D.SALES_ORDER_DOC_SD' THEN [t39].[ITEM_SPECIFICATION] WHEN N'STOCKING_PLAN.STOCKING_PLAN_D' THEN [t32].[ITEM_SPECIFICATION] WHEN N'INNER_ORDER_DOC.INNER_ORDER_DOC_D.INNER_ORDER_DOC_SD' THEN [t40].[ITEM_SPECIFICATION] WHEN N'FORECAST.FORECAST_D' THEN [t42].[ITEM_SPECIFICATION] END AS [REFERENCE_SOURCE_ID_ITEM_SPECIFICATION], CASE [t16].[DEMAND_DOC_RTK] WHEN N'MO' THEN [t43].[ITEM_FEATURE_CODE] WHEN N'DISTRIBUTION_LIST' THEN [t44].[ITEM_FEATURE_CODE] WHEN N'SALES_ORDER_DOC.SALES_ORDER_DOC_D.SALES_ORDER_DOC_SD' THEN [t45].[ITEM_FEATURE_CODE] WHEN N'STOCKING_PLAN.STOCKING_PLAN_D' THEN [t32].[ITEM_FEATURE_CODE] WHEN N'INNER_ORDER_DOC.INNER_ORDER_DOC_D.INNER_ORDER_DOC_SD' THEN [t46].[ITEM_FEATURE_CODE] END AS [EFERENCE_SOURCE_ID_ITEM_FEATURE_CODE], CASE [t16].[DEMAND_DOC_RTK] WHEN N'MO' THEN [t43].[ITEM_SPECIFICATION] WHEN N'DISTRIBUTION_LIST' THEN [t44].[ITEM_SPECIFICATION] WHEN N'SALES_ORDER_DOC.SALES_ORDER_DOC_D.SALES_ORDER_DOC_SD' THEN [t45].[ITEM_SPECIFICATION] WHEN N'STOCKING_PLAN.STOCKING_PLAN_D' THEN [t32].[ITEM_FEATURE_SPEC] WHEN N'INNER_ORDER_DOC.INNER_ORDER_DOC_D.INNER_ORDER_DOC_SD' THEN [t46].[ITEM_SPECIFICATION] END AS [EFERENCE_SOURCE_ID_ITEM_FEATURE_SPECIFICATION], [t16].[DEMAND_QTY] AS [DEMAND_QTY], CASE [t16].[DEMAND_DOC_RTK] WHEN N'SALES_ORDER_DOC.SALES_ORDER_DOC_D.SALES_ORDER_DOC_SD' THEN [t17].[PLAN_DELIVERY_DATE] WHEN N'STOCKING_PLAN.STOCKING_PLAN_D' THEN [t32].[FORECAST_DATE] END AS [PLAN_DELIVERY_DATE], CASE [t16].[DEMAND_DOC_RTK] WHEN N'SALES_ORDER_DOC.SALES_ORDER_DOC_D.SALES_ORDER_DOC_SD' THEN [t47].[CUSTOMER_NAME] END AS [DEMAND_DOC_CUSTOMER_NAME], [t16].[LOCKED_FLAG] AS [LOCKED_FLAG], [t16].[REMARK] AS [MO_DEMAND_REMARK], [t0].[ApproveStatus] AS [ASQ_ApproveStatus], [t4].[ITEM_FEATURE_CODE] AS [ITEM_FEATURE_CODE], [t4].[ITEM_SPECIFICATION] AS [ITEM_FEATURE_ID_ITEM_SPECIFICATION], [t0].[MO_ID] AS [MO_ID], [t1].[PLANT_ID] AS [PLANT_ID], [t0].[SOURCE_ID_ROid] AS [ROid], [t0].[ApproveStatus] AS [APPROVESTATUS], CASE [t0].[SOURCE_ID_RTK] WHEN N'SUPPLIER' THEN [t6].[SUPPLIER_CODE] WHEN N'WORK_CENTER' THEN [t7].[WORK_CENTER_CODE] END AS [SOURCE_ID_CODE], [t0].[EFNETStatus] AS [EFNETStatus], [t0].[ProcessInstanceId] AS [Sys_Qc_ProcessInstanceId], [t0].[ApproveStatus] AS [Sys_Qc_ApproveStatus], ISNULL( LEN( SUBSTRING ([t0].[Attachments], 0, 2) ), 0 ) AS [Sys_Qc_Attachments], [t0].[CreateDate] AS [Sys_Qc_CreateDate], [t48].[LOGONNAME] AS [Sys_Qc_CreateBy_CODE], [t48].[USER_NAME] AS [Sys_Qc_CreateBy_NAME], [t0].[ModifiedDate] AS [Sys_Qc_ModifiedDate], [t49].[LOGONNAME] AS [Sys_Qc_ModifiedBy_CODE], [t49].[USER_NAME] AS [Sys_Qc_ModifiedBy_NAME], [t0].[LastModifiedDate] AS [Sys_Qc_LastModifiedDate], [t50].[LOGONNAME] AS [Sys_Qc_LastModifiedBy_CODE], [t50].[USER_NAME] AS [Sys_Qc_LastModifiedBy_NAME], [t0].[ApproveDate] AS [Sys_Qc_ApproveDate], [t51].[LOGONNAME] AS [Sys_Qc_ApproveBy_CODE], [t51].[USER_NAME] AS [Sys_Qc_ApproveBy_NAME], [t0].[MO_ID] AS [sys_MainId] FROM [MO] AS [t0] LEFT OUTER JOIN [PLANT] AS [t1] ON [t0].[Owner_Org_ROid] = [t1].[PLANT_ID] LEFT OUTER JOIN [DOC] AS [t2] ON [t0].[DOC_ID] = [t2].[DOC_ID] LEFT OUTER JOIN [ITEM] AS [t3] ON [t0].[ITEM_ID] = [t3].[ITEM_BUSINESS_ID] LEFT OUTER JOIN [ITEM_FEATURE] AS [t4] ON [t0].[ITEM_FEATURE_ID] = [t4].[ITEM_FEATURE_ID] LEFT OUTER JOIN [UNIT] AS [t5] ON [t0].[BUSINESS_UNIT_ID] = [t5].[UNIT_ID] LEFT OUTER JOIN [SUPPLIER] AS [t6] ON [t0].[SOURCE_ID_ROid] = [t6].[SUPPLIER_BUSINESS_ID] LEFT OUTER JOIN [WORK_CENTER] AS [t7] ON [t0].[SOURCE_ID_ROid] = [t7].[WORK_CENTER_ID] LEFT OUTER JOIN [ADMIN_UNIT] AS [t8] ON [t0].[ADMIN_UNIT_ID] = [t8].[ADMIN_UNIT_ID] LEFT OUTER JOIN [ITEM_ROUTING] AS [t9] ON [t0].[ITEM_ROUTING_ID] = [t9].[ITEM_ROUTING_ID] LEFT OUTER JOIN [MO] AS [t10] ON [t0].[SOURCE_MO_ID] = [t10].[MO_ID] LEFT OUTER JOIN [MO] AS [t11] ON [t0].[UP_MO_ID] = [t11].[MO_ID] LEFT OUTER JOIN [MO] AS [t12] ON [t0].[PARA_MO_ID] = [t12].[MO_ID] LEFT OUTER JOIN [ADMIN_UNIT] AS [t13] ON [t0].[Owner_Dept] = [t13].[ADMIN_UNIT_ID] LEFT OUTER JOIN [EMPLOYEE] AS [t14] ON [t0].[Owner_Emp] = [t14].[EMPLOYEE_ID] LEFT OUTER JOIN [PROJECT] AS [t15] ON [t0].[PROJECT_ID] = [t15].[PROJECT_ID] LEFT OUTER JOIN [MO_DEMAND] AS [t16] ON [t0].[MO_ID] = [t16].[MO_ID] LEFT OUTER JOIN [SALES_ORDER_DOC_SD] AS [t17] ON [t16].[DEMAND_DOC_ROid] = [t17].[SALES_ORDER_DOC_SD_ID] LEFT OUTER JOIN [SALES_ORDER_DOC_D] AS [t18] ON [t17].[SALES_ORDER_DOC_D_ID] = [t18].[SALES_ORDER_DOC_D_ID] LEFT OUTER JOIN [SALES_ORDER_DOC] AS [t19] ON [t18].[SALES_ORDER_DOC_ID] = [t19].[SALES_ORDER_DOC_ID] LEFT OUTER JOIN [SALES_ORDER_DOC_SD] AS [t20] ON [t16].[DEMAND_DOC_ROid] = [t20].[SALES_ORDER_DOC_SD_ID] LEFT OUTER JOIN [SALES_ORDER_DOC_D] AS [t21] ON [t20].[SALES_ORDER_DOC_D_ID] = [t21].[SALES_ORDER_DOC_D_ID] LEFT OUTER JOIN [SALES_ORDER_DOC_SD] AS [t22] ON [t16].[DEMAND_DOC_ROid] = [t22].[SALES_ORDER_DOC_SD_ID] LEFT OUTER JOIN [TRANSFER_REQUISITION_D] AS [t23] ON [t16].[DEMAND_DOC_ROid] = [t23].[TRANSFER_REQUISITION_D_ID] LEFT OUTER JOIN [TRANSFER_REQUISITION] AS [t24] ON [t23].[TRANSFER_REQUISITION_ID] = [t24].[TRANSFER_REQUISITION_ID] LEFT OUTER JOIN [TRANSFER_REQUISITION_D] AS [t25] ON [t16].[DEMAND_DOC_ROid] = [t25].[TRANSFER_REQUISITION_D_ID] LEFT OUTER JOIN [INNER_ORDER_DOC_SD] AS [t26] ON [t16].[DEMAND_DOC_ROid] = [t26].[INNER_ORDER_DOC_SD_ID] LEFT OUTER JOIN [INNER_ORDER_DOC_D] AS [t27] ON [t26].[INNER_ORDER_DOC_D_ID] = [t27].[INNER_ORDER_DOC_D_ID] LEFT OUTER JOIN [INNER_ORDER_DOC] AS [t28] ON [t27].[INNER_ORDER_DOC_ID] = [t28].[INNER_ORDER_DOC_ID] LEFT OUTER JOIN [INNER_ORDER_DOC_SD] AS [t29] ON [t16].[DEMAND_DOC_ROid] = [t29].[INNER_ORDER_DOC_SD_ID] LEFT OUTER JOIN [INNER_ORDER_DOC_D] AS [t30] ON [t29].[INNER_ORDER_DOC_D_ID] = [t30].[INNER_ORDER_DOC_D_ID] LEFT OUTER JOIN [INNER_ORDER_DOC_SD] AS [t31] ON [t16].[DEMAND_DOC_ROid] = [t31].[INNER_ORDER_DOC_SD_ID] LEFT OUTER JOIN [STOCKING_PLAN_D] AS [t32] ON [t16].[DEMAND_DOC_ROid] = [t32].[STOCKING_PLAN_D_ID] LEFT OUTER JOIN [STOCKING_PLAN] AS [t33] 