AND [t0].[DOC_NO] = #{doc_no}
AND [t0].[DEMAND_NO] like concat('%', #{demand_no}, '%')
AND [t0].[STATUS] = #{status}
AND [t3].[ITEM_CODE] = #{item_id_item_code}
AND [t2].[DOC_NAME] = #{doc_id_doc_name}
AND [t2].[DOC_NAME] = '总装生产任务单'
AND [t0].[DOC_DATE] >= #{params.beginTime}
AND [t0].[DOC_DATE] <= #{params.endTime}
